using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;
    private static ReportingConfiguration _reportingConfiguration = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = _app.Services.GetRequiredService<IChatClient>();

        _reportingConfiguration = new ReportingConfiguration(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "evaluation-reports"));
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        await _app.DisposeAsync();
        await _appHost.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_Response_IsRelevant()
    {
        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(_evaluatorClient),
            new CoherenceEvaluator(_evaluatorClient),
            new FluencyEvaluator(_evaluatorClient),
        };

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Response_IsRelevant),
            evaluators: evaluators);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        var result = await scenario.EvaluateAsync(messages);

        foreach (var metric in result.Metrics)
        {
            Assert.IsFalse(metric.Value.Diagnostics?.HasFailures ?? false,
                $"Metric '{metric.Key}' reported failures.");
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsGrounded()
    {
        var evaluators = new IEvaluator[]
        {
            new GroundednessEvaluator(_evaluatorClient),
        };

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Response_IsGrounded),
            evaluators: evaluators);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Only answer based on provided context."),
            new(ChatRole.User, "Based on the following context, what is the population of Paris? Context: Paris is the capital of France with a population of approximately 2.1 million people in the city proper.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        var result = await scenario.EvaluateAsync(messages);

        foreach (var metric in result.Metrics)
        {
            Assert.IsFalse(metric.Value.Diagnostics?.HasFailures ?? false,
                $"Metric '{metric.Key}' reported failures.");
        }
    }
}

